<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
if(empty($_SESSION['admin_id']))redirect('index.php');
require_once dirname(__DIR__).'/private/planning_store.php';
require_once dirname(__DIR__).'/private/day_view.php';
$operations=opsReady($pdo);
$day=(string)($_GET['date']??date('Y-m-d'));if(!zgsValidDate($day))$day=date('Y-m-d');
$monday=(new DateTimeImmutable($day,new DateTimeZone('Europe/Berlin')))->modify('monday this week')->format('Y-m-d');
$view=($_GET['view']??'day')==='week'?'week':'day';$back='planner.php?date='.$day.'&view='.$view;
$error=$_SESSION['plan_error']??'';unset($_SESSION['plan_error']);$notice=$_SESSION['plan_notice']??'';unset($_SESSION['plan_notice']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 checkCsrf();try{
  $action=(string)($_POST['action']??'');$id=(int)($_POST['task_id']??0);
  if($action==='generate'){$generated=zgsGenerateDueTasks($pdo,date('Y-m-d'));$_SESSION['plan_notice']=$generated['created'].' fällige Aufgaben erstellt.'.($generated['backlog_jobs']?' Rückstand noch vorhanden: erneut begrenzt aktualisieren.':' Bereits vorhandene Aufgaben bleiben erhalten.');}
  elseif($action==='preview'){$token=planSaveProposal($pdo,(int)$_SESSION['admin_id'],$monday,($_POST['scope']??'week')==='day'?$day:null);redirect($back.'&proposal='.$token);}
  elseif($action==='apply'){planApply($pdo,(int)$_SESSION['admin_id'],(string)($_POST['token']??''));if(($_SESSION['planning_proposal_token']??'')===($_POST['token']??''))unset($_SESSION['planning_proposal_token']);$_SESSION['plan_notice']='Vorschlag übernommen; manuelle Sperren und erledigte Aufgaben erhalten.';}
  elseif($action==='toggle'){if($operations){$q=$pdo->prepare('SELECT done FROM tasks WHERE id=?');$q->execute([$id]);$done=$q->fetchColumn();if($done===false)throw new RuntimeException('Aufgabe nicht gefunden.');opsSetDone($pdo,(int)$_SESSION['admin_id'],$id,isset($_POST['done'])?$_POST['done']==='1':!(bool)$done,opsVersion($_POST));}else $pdo->prepare('UPDATE tasks SET done=1-done WHERE id=?')->execute([$id]);}
  elseif($action==='move'){$to=(string)($_POST['to_date']??'');if(!zgsValidDate($to))throw new InvalidArgumentException('Bitte ein gültiges Datum wählen.');$q=$pdo->prepare('SELECT * FROM tasks WHERE id=?');$q->execute([$id]);$t=$q->fetch();if(!$t)throw new RuntimeException('Aufgabe nicht gefunden.');if($t['done'])throw new RuntimeException('Erledigte Aufgaben werden nicht verschoben.');$lo=$t['window_start'];$hi=$t['window_end'];if(($lo&&$to<$lo)||($hi&&$to>$hi)){$lo=$to;$hi=$to;}$args=[$t['title'],$to,(string)($t['notes']??''),$t['duration_minutes']===null?null:(int)$t['duration_minutes'],$t['start_time']?:null,$t['priority'],(int)$t['sort_order'],$lo?:null,$hi?:null];if($operations)opsSaveTask($pdo,(int)$_SESSION['admin_id'],$args,(int)($t['property_id']??0),$id,false,opsVersion($_POST));else $pdo->prepare('UPDATE tasks SET due_date=?,window_start=?,window_end=?,plan_locked=1 WHERE id=?')->execute([$to,$lo,$hi,$id]);$_SESSION['plan_notice']=($t['title']).' verschoben auf '.gszRelativeDay($to).'.';}
  elseif($action==='task'){
   $args=planValidateTask($_POST);$pid=(int)($_POST['property_id']??0);
   if($pid){$s=$pdo->prepare('SELECT id FROM properties WHERE id=?');$s->execute([$pid]);if(!$s->fetchColumn())throw new InvalidArgumentException('Objekt unbekannt.');}
   if($operations)opsSaveTask($pdo,(int)$_SESSION['admin_id'],$args,$pid,$id,isset($_POST['unlock']),opsVersion($_POST));
   else if($id)$pdo->prepare('UPDATE tasks SET title=?,due_date=?,notes=?,duration_minutes=?,start_time=?,priority=?,sort_order=?,window_start=?,window_end=?,property_id=?,plan_locked=? WHERE id=?')->execute([...$args,$pid?:null,isset($_POST['unlock'])?0:1,$id]);
   else $pdo->prepare('INSERT INTO tasks(title,due_date,notes,duration_minutes,start_time,priority,sort_order,window_start,window_end,property_id,plan_locked) VALUES(?,?,?,?,?,?,?,?,?,?,1)')->execute([...$args,$pid?:null]);
  }elseif($action==='appointment'){
   $d=(string)($_POST['appointment_day']??'');$start=(string)($_POST['appointment_start']??'');$end=(string)($_POST['appointment_end']??'');$title=trim((string)($_POST['appointment_title']??''));$address=trim((string)($_POST['address']??''));
   if(!zgsValidDate($d)||planMinute($start)>=planMinute($end)||$title===''||mb_strlen($title)>190||mb_strlen($address)>255)throw new InvalidArgumentException('Termin: Datum, Beschreibung und Ende nach Beginn erforderlich.');
   if($operations)opsSaveAppointment($pdo,(int)$_SESSION['admin_id'],$_POST,(int)($_POST['appointment_id']??0));else $pdo->prepare('INSERT INTO planning_appointments(day,start_time,end_time,title,address) VALUES(?,?,?,?,?)')->execute([$d,$start,$end,$title,$address]);
  }elseif($action==='remove_appointment'){if($operations)opsCancelAppointment($pdo,(int)$_SESSION['admin_id'],(int)($_POST['appointment_id']??0),opsVersion($_POST));else $pdo->prepare('DELETE FROM planning_appointments WHERE id=?')->execute([(int)($_POST['appointment_id']??0)]);}
  elseif($action==='settings'){
   $start=(string)($_POST['day_start']??'');$target=(string)($_POST['target']??'');$warn=(string)($_POST['warning']??'');$buffer=filter_var($_POST['buffer']??'',FILTER_VALIDATE_INT);$destination=trim((string)($_POST['destination']??''));
   if(planMinute($start)>=planMinute($target)||planMinute($target)>=planMinute($warn)||$buffer===false||$buffer<0||$buffer>120||mb_strlen($destination)>190)throw new InvalidArgumentException('Start < Ziel < Warnschwelle; Puffer 0–120 Minuten.');
   $v1Settings=gszV1Ready($pdo);if($v1Settings){$mask=filter_var($_POST['workdays_mask']??31,FILTER_VALIDATE_INT);$cap=(string)($_POST['capacity_end_time']??$warn);if(!$mask||$mask<1||$mask>127||planMinute($cap)<planMinute($target))throw new InvalidArgumentException('Arbeitstage/Kapazitätsende prüfen.');}$pdo->beginTransaction();
   $pdo->prepare('UPDATE planning_settings SET start_time=?,target_time=?,warning_time=?,buffer_minutes=?,evening_destination=? WHERE id=1')->execute([$start,$target,$warn,$buffer,$destination]);if($v1Settings)$pdo->prepare('UPDATE planning_settings SET workdays_mask=?,capacity_end_time=? WHERE id=1')->execute([$mask,$cap]);$pdo->commit();
  }elseif($action==='day_start'){
   $start=(string)($_POST['day_start']??'');planMinute($start);$pdo->prepare('INSERT INTO planning_days(day,start_time) VALUES(?,?) ON DUPLICATE KEY UPDATE start_time=VALUES(start_time)')->execute([$day,$start]);
  }else throw new InvalidArgumentException('Unbekannte Aktion.');
 if(in_array($action,['toggle','task','move','appointment','remove_appointment','generate'],true))gszSuggestWeek($pdo,(int)$_SESSION['admin_id']);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['plan_error']=$e instanceof PDOException?'Planung nicht verfügbar. Migration und Datenbank prüfen.':$e->getMessage();}
 $ret=(string)($_POST['return']??'');if($ret==='index.php')redirect('index.php');if(preg_match('~^planner\.php\?[A-Za-z0-9=&_.-]{1,120}$~D',$ret))redirect($ret);redirect($back);
}
$data=null;$proposal=null;$plan=null;
try{
 $data=planLoad($pdo);$starts=array_column($data['starts'],'start_time','day');
 if(isset($_GET['proposal'])){$s=$pdo->prepare('SELECT * FROM planning_proposals WHERE token=? AND admin_id=?');$s->execute([(string)$_GET['proposal'],$_SESSION['admin_id']]);$proposal=$s->fetch();if($proposal&&!empty($proposal['applied_at'])){$notice.=' Vorschlag bereits übernommen; aktueller Plan wird angezeigt.';$proposal=null;}if($proposal)$plan=json_decode($proposal['payload'],true,512,JSON_THROW_ON_ERROR)['plan'];}
 if(!$plan){$group=[];foreach($data['tasks'] as $t)if($t['due_date']>=$monday&&$t['due_date']<=planDate($monday,6))$group[$t['due_date']][]=$t;
  $plan=['days'=>[],'warnings'=>[],'unplaced'=>array_values(array_filter($data['tasks'],fn($t)=>!$t['done']&&(!$t['due_date']||$t['due_date']<$monday)))];
  for($i=0;$i<7;$i++){$d=planDate($monday,$i);$tasks=$group[$d]??[];usort($tasks,fn($a,$b)=>[(int)($a['sort_order']?:$a['planned_order']),$a['start_time']??'99:99',$a['id']]<=>[(int)($b['sort_order']?:$b['planned_order']),$b['start_time']??'99:99',$b['id']]);$apps=array_values(array_filter($data['appointments'],fn($a)=>$a['day']===$d));$plan['days'][$d]=planTimeline($tasks,$apps,$data['settings'],$starts[$d]??$data['settings']['start_time']);$plan['days'][$d]['appointments']=$apps;}
 }
}catch(Throwable $e){$error=$e instanceof PDOException?'Planung benötigt die Phase-2-Migration.':$e->getMessage();}
// Reuse a confirmed route only while its complete business snapshot is current.
if($data&&!$proposal&&$view==='day'){
 try{require_once dirname(__DIR__).'/private/routing_store.php';$confirmed=routeConfirmedDay($pdo,$day);
  if($confirmed&&empty($confirmed['stale'])){$route=$confirmed['route'];$apps=$plan['days'][$day]['appointments'];$plan['days'][$day]=$route['timeline'];$plan['days'][$day]['appointments']=$apps;$plan['days'][$day]['route_metadata']=$route;$plan['days'][$day]['warnings']=array_merge($plan['days'][$day]['warnings'],$route['warnings']);}
  elseif($confirmed)$notice.=' Bestätigte Route inzwischen geändert/veraltet; Route neu berechnen.';
 }catch(PDOException $e){} // Phase-2-only regression fixtures have no routing tables.
}
$properties=$pdo->query('SELECT id,name FROM properties ORDER BY name LIMIT 500')->fetchAll();
function planHidden(string $action,int $id=0):void{echo '<input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="task_id" value="'.$id.'">';}
function planTaskForm(array $t,array $properties,string $day):void { ?>
<form method="post"><?php planHidden('task',(int)($t['id']??0));?><?php if(isset($t['row_version'])):?><input type="hidden" name="row_version" value="<?=(int)$t['row_version']?>"><?php endif?><label>Aufgabe<input name="title" maxlength="190" required value="<?=e($t['title']??'')?>"></label><label>Datum<input type="date" name="due_date" required value="<?=e($t['due_date']??$day)?>"></label><label>Objekt<select name="property_id"><option value="">Ohne Objekt</option><?php foreach($properties as $p):?><option value="<?=(int)$p['id']?>" <?=(int)($t['property_id']??0)===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach?></select></label>
<label>Dauer in Minuten<input type="number" name="duration_minutes" min="1" max="1440" value="<?=e((string)($t['duration_minutes']??''))?>"></label><label>Feste Uhrzeit<input type="time" name="start_time" value="<?=e(substr($t['start_time']??'',0,5))?>"></label><label>Position am Tag (0 = automatisch)<input type="number" name="sort_order" min="0" max="9999" value="<?=(int)($t['sort_order']??0)?>"></label><label>Wichtigkeit<select name="priority"><?php foreach(['urgent'=>'Dringend','high'=>'Hoch','normal'=>'Normal','low'=>'Niedrig'] as $v=>$l):?><option value="<?=e($v)?>" <?=($t['priority']??'normal')===$v?'selected':''?>><?=e($l)?></option><?php endforeach?></select></label><label>Frühestens<input type="date" name="window_start" value="<?=e($t['window_start']??'')?>"></label><label>Spätestens<input type="date" name="window_end" value="<?=e($t['window_end']??'')?>"></label><label>Notiz<textarea name="notes" maxlength="5000"><?=e($t['notes']??'')?></textarea></label><label><input type="checkbox" name="unlock" value="1"> Darf automatisch auf einen anderen Tag gelegt werden</label><button class="primary">Speichern</button></form>
<?php }
$self='planner.php?date='.$day.'&view='.$view;$wd=static fn(string $d)=>gszDayLabel($d);
$range=static function(string $from):string{$a=new DateTimeImmutable($from);$b=$a->modify('+6 days');return (int)$a->format('j').'.'.($a->format('n')!==$b->format('n')?' '.GSZ_MONTHS[(int)$a->format('n')]:'').'–'.(int)$b->format('j').'. '.GSZ_MONTHS[(int)$b->format('n')];};
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($view==='week'?'Woche':gszRelativeDay($day))?> · GSZ</title><link rel="stylesheet" href="zentrale.css"></head><body><main>
<?php if($error):?><p class="error flash" role="alert"><?=e($error)?></p><?php endif?><?php if(trim($notice)!==''):?><p class="notice flash" role="status"><?=e(trim($notice))?></p><?php endif?>
<?php if($view==='day'):?>
<div class="page-head"><div><h1><?=e(gszRelativeDay($day))?></h1><p class="sub"><?=e(gszDayLabel($day,true))?></p></div><nav class="daynav" aria-label="Tag wechseln"><a href="?date=<?=e(planDate($day,-1))?>" aria-label="Vorheriger Tag">‹</a><a href="?date=<?=e(planDate($day,1))?>" aria-label="Nächster Tag">›</a></nav></div>
<?php if($data)echo gszRenderDay($pdo,$day,$self);?>
<details class="card"><summary>Aufgabe hinzufügen</summary><?php planTaskForm(['due_date'=>$day],$properties,$day);?></details>
<details class="card"><summary>Termin hinzufügen</summary><form method="post"><?php planHidden('appointment');?><label>Datum<input type="date" name="appointment_day" value="<?=e($day)?>" required></label><div class="form-grid"><label>Von<input type="time" name="appointment_start" required></label><label>Bis<input type="time" name="appointment_end" required></label></div><label>Was<input name="appointment_title" maxlength="190" required></label><label>Wo (optional)<input name="address" maxlength="255"></label><button class="primary">Termin speichern</button></form></details>
<?php if($data):?><details class="card"><summary>Tagesbeginn und Route</summary><form method="post"><?php planHidden('day_start');?><label>Beginn an diesem Tag<input type="time" name="day_start" value="<?=e(substr($starts[$day]??$data['settings']['start_time'],0,5))?>" required></label><button>Speichern</button></form><p><a href="route.php?date=<?=e($day)?>">Reihenfolge und Fahrtzeiten ansehen</a></p></details><?php endif?>
<?php else:?>
<div class="page-head"><div><h1>Woche</h1><p class="sub"><?=e($range($monday))?></p></div><nav class="daynav" aria-label="Woche wechseln"><a href="?date=<?=e(planDate($monday,-7))?>&amp;view=week" aria-label="Vorherige Woche">‹</a><a href="?date=<?=e(planDate($monday,7))?>&amp;view=week" aria-label="Nächste Woche">›</a></nav></div>
<?php if($proposal):?><section class="card"><h2>Vorschlag für die Woche</h2><p>So würden die offenen Aufgaben verteilt. Feste Termine und von dir verschobene Aufgaben bleiben, wie sie sind.</p><div class="actions"><form method="post"><?php planHidden('apply');?><input type="hidden" name="token" value="<?=e($proposal['token'])?>"><button class="primary">Vorschlag übernehmen</button></form><a class="btn" href="planner.php?date=<?=e($day)?>&amp;view=week">Verwerfen</a></div></section><?php endif?>
<?php if($data):foreach($plan['days'] as $d=>$daily):$rows=$daily['rows'];$open=count(array_filter($rows,fn($r)=>!$r['task']['done']));?>
<section class="week-day<?=$d===date('Y-m-d')?' is-today':''?>"><h2><a href="planner.php?date=<?=e($d)?>"><?=e(gszRelativeDay($d))?><?=in_array(gszRelativeDay($d),['Heute','Morgen','Gestern'],true)?' · '.e((new DateTimeImmutable($d))->format('j.n.')):''?></a><span class="count"><?=$open?($open===1?'1 offen':$open.' offen'):($rows?'erledigt':'')?></span></h2>
<?php if($rows||$daily['appointments']):?><div class="rows"><?php foreach($daily['appointments'] as $a):?><div class="row"><div class="t"><strong><?=e($a['title'])?></strong><span>Termin <?=e(substr($a['start_time'],0,5).'–'.substr($a['end_time'],0,5))?></span></div></div><?php endforeach?><?php foreach($rows as $row):$t=$row['task'];?><a class="row<?=$t['done']?' is-done':''?>" href="<?=$t['id']?'task.php?id='.(int)$t['id']:'#'?>"><span class="t"><strong><?=e($t['property_name']??'Ohne Objekt')?></strong><span><?=e($t['title'])?></span></span><span class="end"><?=$t['done']?'✓':($t['start_time']?e(substr($t['start_time'],0,5)):'')?></span></a><?php endforeach?></div><?php else:?><p class="muted">Frei.</p><?php endif?></section>
<?php endforeach;endif?>
<?php if($data&&$plan['unplaced']&&!$proposal):?><section class="week-day"><h2>Noch ohne Tag</h2><div class="rows"><?php foreach(array_slice($plan['unplaced'],0,30) as $t):?><a class="row" href="task.php?id=<?=(int)$t['id']?>"><span class="t"><strong><?=e($t['property_name']??'Ohne Objekt')?></strong><span><?=e($t['title'])?></span></span><span class="end"><?=e($t['due_date']?'seit '.(new DateTimeImmutable($t['due_date']))->format('j.n.'):'')?></span></a><?php endforeach?></div></section><?php endif?>
<?php if($data):?><details class="card"><summary>Planung</summary><div class="actions"><form method="post"><?php planHidden('preview');?><input type="hidden" name="scope" value="week"><button>Woche neu vorschlagen</button></form><form method="post"><?php planHidden('generate');?><button>Regelaufgaben aktualisieren</button></form></div><p class="hint">Regelaufgaben werden sonst automatisch per Cron angelegt.</p><p><a href="waste_export.php?from=<?=e($monday)?>&amp;to=<?=e(planDate($monday,55))?>&amp;format=ics">Tonnen-Termine für den Kalender (ICS)</a> · <a href="waste_export.php?from=<?=e($monday)?>&amp;to=<?=e(planDate($monday,55))?>&amp;format=csv">als Tabelle (CSV)</a></p></details>
<details class="card"><summary>Arbeitszeiten</summary><form method="post"><?php planHidden('settings');if(gszV1Ready($pdo)):?><input type="hidden" name="workdays_mask" value="<?=(int)$data['settings']['workdays_mask']?>"><input type="hidden" name="capacity_end_time" value="<?=e(substr($data['settings']['capacity_end_time'],0,5))?>"><?php endif?><div class="form-grid"><label>Tagesbeginn<input type="time" name="day_start" value="<?=e(substr($data['settings']['start_time'],0,5))?>" required></label><label>Feierabend-Ziel<input type="time" name="target" value="<?=e(substr($data['settings']['target_time'],0,5))?>" required></label><label>Spätestens fertig<input type="time" name="warning" value="<?=e(substr($data['settings']['warning_time'],0,5))?>" required></label><label>Minuten zwischen zwei Objekten<input type="number" name="buffer" min="0" max="120" value="<?=(int)$data['settings']['buffer_minutes']?>"></label></div><label>Ziel am Abend (optional)<input name="destination" maxlength="190" value="<?=e($data['settings']['evening_destination'])?>"></label><button>Speichern</button></form></details><?php endif?>
<?php endif?>
